(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(y*0.012+t*0.3)*20 + Math.cos(x*0.015-t*0.2)*15;
  const w1y = Math.cos(x*0.013-t*0.25)*18 + Math.sin(y*0.016+t*0.35)*12;
  const w2x = Math.sin((y+w1y)*0.02+t*0.5)*10 + Math.cos((x+w1x)*0.018-t*0.4)*8;
  const w2y = Math.cos((x+w1x)*0.019-t*0.45)*9 + Math.sin((y+w1y)*0.021+t*0.55)*7;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.5],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.75],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.65],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.13, 1.8, 0.85]
  ];
  let aS = 0, iS = 0, cS = 0, wT = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    cS += Math.sin(d*f*1.3 - t*sp*0.8 + 3.0) * w * 0.5;
    wT += w;
  }
  const act = aS/wT, inh = iS/wT, cross = cS/wT;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1) +
    Math.sin(sx*0.07+sy*0.06-t*0.9)*0.5 + Math.sin(sx*0.05-sy*0.08+t*1.3)*0.4)/3.4 +
    Math.sin((sx+sy)*0.12+t*2.5)*0.15 + Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.35;
  const sp2 = (Math.sin(dist*0.07+ang*2+t*0.8) + Math.cos(dist*0.06-ang*5+t*1.0))*0.2;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + sp1)*2.2);
  const rd2 = Math.tanh((cross - act*0.5 + inh*0.4 + sp2)*1.8);
  const reaction = rd1*0.7 + rd2*0.3;
  const cellPh = Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5 +
    Math.sin((sx*0.7-sy*1.3)*0.08+t*0.7)*0.3;
  const cell = Math.tanh(cellPh*1.5)*0.3;
  const fil = Math.sin(Math.sin(sx*0.08+t*0.3)*5+sy*0.12)*Math.sin(Math.sin(sy*0.07-t*0.4)*4+sx*0.1)*0.15;
  const blend = reaction*0.6 + cell*0.2 + fil*0.1 + bg*0.1;
  const v = Math.tanh(blend*1.5)*0.5+0.5;
  const pal = [
    [5,12,48],[12,45,82],[18,90,120],[30,140,135],[80,180,130],
    [170,200,90],[220,190,70],[240,150,60],[230,100,70],[190,60,80],
    [130,35,75],[70,20,60],[30,12,50],[5,12,48]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge = Math.abs(reaction)>0.65?1.12:1.0;
  const shimmer = 1.0+Math.sin(t*3+dist*0.1)*0.05*(Math.abs(rd2)>0.5?1:0);
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*shimmer)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*shimmer)|0
  ];
}
